import { P, H, L, O, N, C, task, check, faq, n, A, les } from '../kit.js';
import { code } from './files.js';
import { RAN, PARTLY, SETUP, run } from './kit2.js';

const S = 'Ten Portfolio Projects';

const HOWTO = (deps, lib, test, dev = 'supertest') => SETUP(deps, [
  `Copy \`p-kit.js\`, \`${lib}\` and \`${test}\` into the folder. The shared \`p-kit.js\` is in Project 1.`,
  `Install the test tools with \`npm install -D ${dev}\`, then run \`node --test ${test}\`.`,
]);

const NOTE_MEMORY = N("To keep every project runnable with no setup, the data is kept in memory and disappears when the server restarts. The first extension task of every project is to move the store to MongoDB or PostgreSQL. The rules and the tests stay the same, which is exactly why the code is split into layers.");

const RESUME = (text) => P(`**On your resume.** ${text} Write only what you really built and can explain, and keep the repository link next to it. Our [resume templates](/templates) have a project section that suits this, and the [ATS checker](/features/ats-checker) shows how a tracking system reads it.`);

function project({ dev, no, slug, title, meta, desc, intro, build, design, files, rules, security, tasks, checks, resume, anim, faqs, deps, lib, test, extra = [] }) {
  return les(S, slug, `Project ${no}: ${title}`, meta, desc, [
    P(intro),
    H('What you will build'),
    L(...build),
    H('Design decisions before any code'),
    ...design.map((t) => P(t)),
    HOWTO(deps, lib, test, dev),
    ...files.flatMap(([name, label]) => [P(label), C(name.endsWith('.yml') ? 'yaml' : 'js', code(name))]),
    H('Rules worth understanding'),
    ...rules.flatMap(([head, text]) => [P(`**${head}.** ${text}`)]),
    H('Security and honesty notes'),
    ...security.map((t) => P(t)),
    ...extra,
    RAN,
    NOTE_MEMORY,
    H('Extend it'),
    ...task(...tasks),
    ...check(...checks),
    RESUME(resume),
  ], anim, faqs);
}

export const lessons = [
  project({
    no: 1, slug: 'project-1-crud-rest-api-for-users-with-validation-and-paging',
    title: 'A CRUD REST API for Users', meta: 'Project 1: Users CRUD REST API',
    desc: 'Build your first complete Express REST API: create, read, update and delete users with validation, paging, search, unique emails and correct status codes.',
    deps: 'express jsonwebtoken', lib: 'p01-users.js', test: 'p01.test.js',
    intro: "Every back end developer builds a CRUD API first, and interviewers still ask to see one. CRUD stands for create, read, update and delete, the four things you do with almost any kind of data. This project is small enough to finish in an evening, and complete enough to show that you know the details that separate a tutorial from real work: validation, unique emails, paging, search, the difference between PUT and PATCH, and honest status codes. All ten projects in this part of the course follow the same pattern: a short description, the code, the rules that matter, and a test that proves them.",
    build: ["`POST /api/users` creates a user and returns **201** with a `Location` header.", "`GET /api/users` lists users with `page`, `limit` and a search word `q`.", "`GET`, `PUT`, `PATCH` and `DELETE` on `/api/users/:id`.", "Clean validation messages with **422**, a duplicate email with **409**, a missing user with **404**, and delete with **204**."],
    design: ["A user has an id, a name, an email, an optional age and a creation time. Before writing code, decide the rules, because rules are the real content of an API. A name needs at least two letters. An email must look like an email, is trimmed and turned into lower case, and must be unique, so that `ASHA@Example.com` and `asha@example.com` cannot be two people. An age, if sent, must be a whole number between 0 and 120.", "The shape of the code follows lesson 19. The `clean` function checks and cleans a body and throws an `AppError` with the right status code, and one error handler at the bottom turns errors into JSON replies. The shared file `p-kit.js` holds `AppError` and the handlers, and the later projects reuse it, so read it first."],
    files: [['p-kit.js', "First the shared helpers. `AppError` carries a status code, `requireAuth` and `requireRole` protect routes, and `errorHandler` makes sure that a bug never shows its stack trace to the client."], ['p01-users.js', "Now the project. Read `clean`, then `createApp`, and notice how short each route is, because the rules live in `clean` and in two small helpers."], ['p01.test.js', "The test goes through the whole life of a user and checks each rule."]],
    rules: [["PUT replaces, PATCH changes", "A `PUT` sends the whole new version of the user, so a field that you leave out disappears. A `PATCH` sends only what changes, so the rest stays. The test shows this with the `age` field: after a `PATCH` it is still there, and after a `PUT` it is gone. Many APIs use `PUT` for both, and that is a common source of confusion."], ["Conflict is not invalid", "A malformed email is **422**: the data fails the rules. A duplicate email is **409**: the data is fine, but it clashes with something that already exists. Telling the two apart lets a front end show the right message."], ["Paging and search together", "The list route clamps `limit` to 50, falls back to defaults for bad numbers, and applies the search before slicing the page, so that `total` in the reply counts the matches and not all users. Front ends use that number to draw page buttons."], ["A missing user inside a helper", "The `find` helper throws a 404 `AppError`, so every route that needs a user is a single line and none of them can forget to check."]],
    security: ["There is no login in this first project, so anyone can call it. In a real system these routes sit behind the authentication of Project 2. The body is never copied straight into the stored user: `clean` builds a new object with only the allowed fields, which protects you from a client sending extra fields such as `isAdmin`.", "The email check here is a simple pattern. The only real proof that an address works is to send a message to it, as lesson 28 does."],
    tasks: ["Move the store to MongoDB with Mongoose and add a unique index on the email.", "Add sorting with an allow-list of fields.", "Write the OpenAPI file for these routes, as in lesson 21, and open it in Swagger UI."],
    checks: ["Your test passes.", "A duplicate email returns 409 and a bad email returns 422.", "You can explain the difference between PUT and PATCH using the age field."],
    resume: "A line such as \"Built a REST API with Express, with validation, paging, search and automated tests with Supertest\" is honest and specific.",
    anim: A('One CRUD request', [n('c', 'Client', 'POST /api/users', 0, 0, 'user'), n('v', 'clean()', 'validate and trim', 1, 0, 'check'), n('s', 'Store', 'Map or database', 2, 0, 'store'), n('r', 'Reply', '201 + Location', 3, 0, 'out')], [
      { say: 'A client sends a JSON body.', on: ['c'] }, { say: 'The clean function checks every field and throws a 422 error with a clear message.', flow: ['c>v:body'] },
      { say: 'The store checks that the email is unique, otherwise a 409 conflict.', flow: ['v>s:clean data'] }, { say: 'The reply is 201 with the new user and its URL in the Location header.', flow: ['s>r:created'] }]),
    faqs: [faq('Why is 409 used for a duplicate email?', 'The data is valid but conflicts with existing data. 422 is for data that breaks the rules.'), faq('Should the id be a number or a string?', 'Databases such as MongoDB use string ids. Numbers are simple for learning. Either way, treat the id as text from the URL and convert it on purpose.'), faq('Why return a Location header?', 'It tells the client the URL of the new item, which is the REST convention for 201 Created.')],
  }),

  project({
    no: 2, slug: 'project-2-authentication-system-with-jwt-refresh-and-password-reset',
    title: 'An Authentication System', meta: 'Project 2: Authentication, JWT and Reset',
    desc: 'Build a complete login system in Express: register, log in with bcrypt and JWT, rotate refresh tokens, reset a forgotten password and protect routes.',
    deps: 'express jsonwebtoken bcryptjs', lib: 'p02-auth.js', test: 'p02.test.js',
    intro: "Login is the first feature that every real product needs, and the one where mistakes hurt most. This project puts together the ideas of lessons 27 and 28 into one working service that you could put in front of any other app: registration, login, refresh tokens that rotate, a forgot-password flow that does not reveal who has an account, and a protected route. It is a strong project for a portfolio, because many candidates only show a login form, and few show that they understand what happens behind it.",
    build: ["`POST /auth/register` with validation and password hashing.", "`POST /auth/login` that returns a short-lived access token and a refresh token.", "`POST /auth/refresh` that rotates the refresh token and refuses a reused one.", "`POST /auth/forgot-password` and `/auth/reset-password` with an expiring, single-use token.", "`GET /me`, a route that needs a valid token."],
    design: ["The service stores a user with a **password hash**, never the password. It stores refresh tokens as hashes with an expiry and a `used` flag. It stores a reset token as a hash with an expiry time. The clock is passed in as `now`, so that the test can move time forward instead of waiting fifteen minutes.", "The only thing the client ever keeps is the two tokens. The access token proves who the user is for a few minutes. The refresh token can only be exchanged once for a new pair. Compare the code with lesson 27 and notice what this project adds: the full password reset."],
    files: [['p02-auth.js', "The service in one file. Read the register and login routes first, then the refresh route, and last the two password routes."], ['p02.test.js', "The test registers, logs in, refreshes, tries to reuse a refresh token, resets a password and checks that the old password no longer works."]],
    rules: [["The same answer for a wrong user and a wrong password", "Login replies `Wrong email or password` in both cases. If it said which one was wrong, an attacker could use the form to find out which emails are registered."], ["Refresh tokens are single-use", "A refresh token is marked used when it is exchanged. If someone presents it again, the server answers 401 and the user has to log in again. A used token appearing a second time is a sign that it was copied."], ["Reset tokens expire and work once", "The token is random, stored only as a hash, valid for a short time, and removed after use. The reply to `forgot-password` is identical whether or not the email exists."], ["Hashing is slow on purpose", "`bcrypt.compare` takes a noticeable fraction of a second, so an attacker who guesses passwords pays that cost on every guess. Use the asynchronous version so the event loop is not blocked, as lesson 39 explains."]],
    security: ["In this project the reset token is handed to a `mailer` object, and the test passes in a fake mailer that remembers it, so that the test can read it. A real service sends it by email, as in lesson 28, and never returns it in the HTTP reply. Add rate limiting to login and forgot-password before you put anything like this online.", "The secret used to sign tokens has a development default in `p-kit.js`. Production must set `JWT_SECRET` to a long random value, and the code should refuse to start without it, as lesson 31 shows."],
    tasks: ["Replace the fake mailer with Nodemailer and a test inbox service.", "Add email verification before the first login.", "Add a `/logout` route that removes the refresh token, and a test for it."],
    checks: ["A used refresh token is refused.", "The reset flow works once and fails the second time.", "Unknown and known emails get the same reply from forgot-password."],
    resume: "\"Implemented JWT authentication with refresh-token rotation, bcrypt password hashing and a secure password reset flow\" is a precise line that interviewers can ask about.",
    anim: A('Login and refresh', [n('r', 'Register', 'bcrypt hash stored', 0, 0, 'user'), n('l', 'Login', 'two tokens', 1, 0, 'tool'), n('f', 'Refresh', 'old token used up', 2, 0, 'check'), n('p', 'Reset', 'token by email, once', 3, 0, 'data')], [
      { say: 'Registration stores only a hash of the password.', on: ['r'] }, { say: 'Login compares the hash and returns a short access token and a refresh token.', flow: ['r>l:password ok'] },
      { say: 'Refreshing swaps the refresh token for a new pair. Reusing the old one fails.', flow: ['l>f:rotate'] }, { say: 'A forgotten password is replaced through an expiring, single-use token.', flow: ['f>p:forgot'] }]),
    faqs: [faq('Why not return the user password hash?', 'Even a hash helps an attacker who steals it. Never send it to a client and never log it.'), faq('How long should an access token live?', 'Common choices are 5 to 15 minutes. The shorter it is, the less a stolen token is worth.'), faq('Do I need both bcrypt and JWT?', 'They do different jobs. bcrypt protects stored passwords. JWT carries the proof of login in requests.')],
  }),

  project({
    no: 3, slug: 'project-3-blog-api-with-categories-comments-and-roles',
    title: 'A Blog API with Roles', meta: 'Project 3: Blog API with Roles',
    desc: 'Build a blog back end in Express with posts, categories, comments and three roles: readers, authors who edit only their own posts, and admins who publish.',
    deps: 'express jsonwebtoken', lib: 'p03-blog.js', test: 'p03.test.js',
    intro: "A blog sounds simple until you ask who may do what. Anyone may read a published post. A logged-in user may comment. An author may write and edit their own posts but not those of others. Only an admin may publish. That list of permissions is what makes this project a good test of your understanding of authorization, and it is a standard portfolio piece for a reason: the data is easy to understand, so the reviewer can concentrate on how you handled the rules.",
    build: ["Public `GET /api/posts` that lists only published posts, with paging, a category filter and search.", "`GET /api/posts/:slug` that shows one published post.", "Authors and admins create, edit and delete posts. Authors only their own.", "`POST /api/posts/:id/publish` for admins only.", "Logged-in users add comments to published posts.", "`GET /api/categories` with the number of posts in each."],
    design: ["Three roles are used: `reader`, `author` and `admin`. A post has a title, a body, a slug made from the title, a category, a status of `draft` or `published`, and the id of its author. New posts always start as drafts, so an author can never publish by mistake or on purpose. Publishing is a separate action with its own route and its own role check.", "Drafts must not leak. The public list and the single-post route filter on `status === 'published'`. A draft asked for by slug answers 404, not 403, because 403 would confirm that the draft exists."],
    files: [['p03-blog.js', "The code uses the helpers from `p-kit.js`: `requireAuth` for logged-in routes and `requireRole` for role checks. Notice that the ownership check for editing and deleting is written inside the route, because it needs the post that it loads."], ['p03.test.js', "The test plays the three roles one after another."]],
    rules: [["Role check first, ownership second", "`requireRole('author', 'admin')` decides whether the kind of user may use the route at all. Then the route loads the post and checks `post.authorId === req.user.id`, unless the user is an admin. Both checks are needed. A role says *what kind of user*, ownership says *whose data*. Forgetting the second check is one of the most common real-world access control bugs, because every author could then edit every post."], ["Slugs", "A slug is the readable part of a URL, such as `my-first-post`. It is made from the title in lower case, with spaces turned into hyphens and strange characters removed, and it must be unique. Good slugs help both people and search engines."], ["Comments belong to published posts only", "A comment on a draft or a missing post returns 404. The text is trimmed and limited to 1000 characters."], ["Counting categories", "The categories route returns each name with its number of posts. With a database this becomes a `$group` stage of an aggregation, as in lesson 25."]],
    security: ["Comments contain text from strangers. The API stores them as they are, and the front end must escape them when drawing the page, as lesson 30 explains. If you allow HTML in posts, clean it with a library such as DOMPurify before you save or show it.", "Never take the author id from the request body. The code uses `req.user.id` from the verified token."],
    tasks: ["Add `GET /api/posts/mine` for an author to see their drafts.", "Add tags with a filter, and an index on them in MongoDB.", "Add a moderation flag to comments and an admin route to hide them."],
    checks: ["An author cannot edit another author's post.", "A draft returns 404 to the public.", "Only an admin can publish."],
    resume: "\"Designed role-based access control for a blog API, with ownership checks, draft and publish workflow and automated tests of every permission\" shows that you understand authorization.",
    anim: A('Who may do what', [n('rd', 'Reader', 'read published', 0, 0, 'user'), n('au', 'Author', 'write own posts', 1, 0, 'tool'), n('ad', 'Admin', 'publish, edit any', 2, 0, 'check'), n('co', 'Comments', 'logged-in users', 3, 0, 'data')], [
      { say: 'Anyone may read published posts. Drafts are never shown.', on: ['rd'] }, { say: 'An author creates drafts and edits only the posts that they own.', flow: ['rd>au:login as author'] },
      { say: 'Only an admin can publish, or change any post.', flow: ['au>ad:role admin'] }, { say: 'Any logged-in user may comment on a published post.', flow: ['ad>co:comment'] }]),
    faqs: [faq('Why return 404 for another author\'s draft?', 'A 403 would confirm that the draft exists. A 404 tells a stranger nothing.'), faq('What is a slug?', 'A readable, unique text in the URL, made from the title, such as my-first-post. It is better for people and for search engines than a number.'), faq('Where should roles be stored?', 'In your database, on the user. They are copied into the token by the server, and never read from the request body.')],
  }),

  project({
    no: 4, slug: 'project-4-e-commerce-backend-with-cart-orders-and-stock',
    title: 'An E-Commerce Back End', meta: 'Project 4: E-Commerce Back End',
    desc: 'Build an online shop back end in Express: products, a cart per user, checkout with server-side prices, stock control and a payment provider behind an interface.',
    deps: 'express jsonwebtoken', lib: 'p04-shop.js', test: 'p04.test.js',
    intro: "An online shop is the classic big portfolio project, and the code behind it is more interesting than the screens. Money is involved, stock is limited, and two customers may want the last item at the same moment. This project builds the core: products, a cart for each user, and checkout. Its real lessons are all about trust: never trust the price sent by the browser, check stock again at the moment of purchase, and never reduce stock for a payment that failed.",
    build: ["`GET /api/products` shows products that are in stock.", "`POST /api/products` lets an admin add a product with a price in cents and a stock count.", "`PUT /api/cart/:productId` sets the quantity of a product in your cart, and 0 removes it.", "`POST /api/orders` turns the cart into an order, charges the payment provider, reduces stock and empties the cart.", "`GET /api/orders` shows the orders of the logged-in user."],
    design: ["Prices are integers in cents. The cart stores only a product id and a quantity. When the customer checks out, the server looks up each price in its own data and calculates the total. The browser has no say in the price. That one rule prevents the oldest trick in e-commerce, changing a price in the browser's developer tools.", "The payment provider is passed into `createApp` as an object with a `charge` function, so the test can use a fake that approves or declines, and a real provider can replace it later without changes to the shop. That is the storage driver idea of lesson 22 applied to money."],
    files: [['p04-shop.js', "The shop in one file. Read the checkout route slowly, because the order of its steps is the whole lesson."], ['p04.test.js', "The test covers an admin adding products, a customer filling a cart, a successful checkout, a declined payment, and a customer who asks for more than is in stock."]],
    rules: [["Checkout order matters", "The route checks that the cart is not empty, looks up every product, checks the stock **again**, adds up the total from the server's prices, charges the provider, and only if the payment works does it reduce stock and create the order. If the payment fails, nothing has changed and the reply is **402**. If the steps were in a different order, a failed payment could still remove stock."], ["Stock races", "In this in-memory version, JavaScript runs one request at a time between awaits, so the check and the update are safe. With a database, two requests can both see 1 item left. The fix is the conditional update of lesson 25: `findOneAndUpdate({ _id, stock: { $gte: qty } }, { $inc: { stock: -qty } })`, which checks and subtracts in one step, or a transaction when several documents are involved."], ["Own data only", "The cart and the order list are found by `req.user.id`. A customer can never read another customer's orders by changing an id in the URL."], ["Hide products that are out of stock", "The product list filters on `stock > 0`, so customers do not see items that they cannot buy."]],
    security: ["Only an admin can add products. The body of that route is checked: a name, an integer price of at least 1, and an integer stock of 0 or more. A price of `-5` or `19.99` is refused.", "In a real shop, the payment goes through a redirect or a hosted page and a webhook, as lesson 37 describes, and the order stays `pending` until the webhook arrives. This project charges directly through the fake provider to keep the stock logic easy to see."],
    tasks: ["Replace the direct charge with the pending order and webhook flow of lesson 37.", "Add product images with the upload code of lesson 22.", "Add a coupon code with a percentage discount that is calculated on the server."],
    checks: ["Changing a price in the request does nothing.", "A declined payment leaves the stock unchanged.", "A customer cannot see another customer's orders."],
    resume: "\"Built the back end of an online shop with server-side pricing in cents, per-user carts, stock control and a payment gateway behind an interface, tested with mock payments\" is a clear, true summary.",
    anim: A('Checkout steps', [n('cart', 'Cart', 'ids and quantities', 0, 0, 'data'), n('price', 'Server prices', 'total in cents', 1, 0, 'check'), n('pay', 'Charge', 'provider interface', 2, 0, 'cloud'), n('ord', 'Order + stock', 'only after payment', 3, 0, 'store')], [
      { say: 'The cart holds only product ids and quantities.', on: ['cart'] }, { say: 'The server looks up each price and checks stock again.', flow: ['cart>price:read'] },
      { say: 'It charges the provider. A decline stops here with 402 and nothing changes.', flow: ['price>pay:amount'] }, { say: 'Only after success does it reduce stock, save the order and clear the cart.', flow: ['pay>ord:paid'] }]),
    faqs: [faq('Why recheck stock at checkout?', 'Stock may have changed since the item was added to the cart. The check at the moment of purchase is the one that counts.'), faq('What is HTTP status 402?', 'Payment Required. It is rarely used but is a clear fit for a declined payment.'), faq('How do I stop two people buying the last item?', 'With a database, use a conditional atomic update or a transaction, so that checking and subtracting happen in one step.')],
  }),

  project({
    no: 5, slug: 'project-5-employee-management-system-with-attendance-and-permissions',
    title: 'An Employee Management System', meta: 'Project 5: Employee Management System',
    desc: 'Build an HR back end in Express: departments, employees, daily attendance check-in and check-out, soft delete and four roles with different data access.',
    deps: 'express jsonwebtoken', lib: 'p05-employees.js', test: 'p05.test.js',
    intro: "Company software is where role-based access control becomes interesting, because the rules are not only about actions but about *which rows* a person may see. An HR officer sees everyone. A manager sees only their department. An employee sees only themselves. This project builds an employee system with departments and attendance, and its main lesson is the idea of **scoping**: the same URL returns different data to different users.",
    build: ["Admins and HR create departments and employees.", "`GET /api/employees` returns all employees to HR and admins, the department to a manager, and only themselves to an employee.", "Soft delete: removing an employee keeps their history.", "Employees check in and check out once a day.", "Admins, HR and managers read attendance."],
    design: ["There are four roles: `admin`, `hr`, `manager` and `employee`. Every employee belongs to a department, and managers belong to the department they manage. A route that lists data must filter by what the caller is allowed to see, and the filter belongs on the server, never in the front end. A front end that hides rows is decoration. The API must refuse to send them.", "Deleting an employee changes a field, `active: false`, instead of removing the record. Attendance history, payroll history and audit trails refer to the person, so the record must stay. Deactivated employees can no longer check in."],
    files: [['p05-employees.js', "Read the list route first, because it contains the scoping rule. Then read the two attendance routes."], ['p05.test.js', "The clock is a parameter again, so the test can pretend that it is a different day without waiting."]],
    rules: [["Scoping by role", "The list route starts with every employee and narrows it: no change for `admin` and `hr`, only the manager's own department for a `manager`, and only the person's own record for an `employee`. Test each role on the same URL and compare the results."], ["One check-in per day", "The attendance record has the employee id and the date. A second check-in on the same date answers **409**. Check-out is allowed only after a check-in, and only once. The date comes from the server clock, in one known time zone, never from the client, because a client could claim any day."], ["Soft delete", "`DELETE` sets `active` to false and keeps the record. Listing, check-in and reports must then agree on how they treat inactive people, and a test should protect that decision."], ["Unique department names", "Names are compared in lower case, so `Sales` and `sales` are the same department and the second one answers 409."]],
    security: ["Personal data about employees is sensitive, and in many countries the law controls how it is stored and who may see it. Collect only what you need, protect it with the role checks shown here, log who reads sensitive records, and ask for professional advice before you use anything like this with real people.", "Time zones are a classic source of bugs. Decide on the zone of the company, and calculate the date in it, rather than using the server's local time by accident."],
    tasks: ["Add leave requests with a status of pending, approved or rejected, approved by the manager.", "Add a monthly attendance report with an aggregation pipeline.", "Add an audit log that records who viewed or changed employee records."],
    checks: ["The same URL returns different rows for each of the four roles.", "A second check-in on one day returns 409.", "A deactivated employee cannot check in."],
    resume: "\"Built an HR API with four roles, department-scoped data access, attendance tracking and soft delete, with tests for each permission\" is a good description.",
    anim: A('Same URL, different rows', [n('ad', 'HR or admin', 'sees everyone', 0, 0, 'check'), n('mg', 'Manager', 'own department', 1, 0, 'tool'), n('em', 'Employee', 'only themselves', 2, 0, 'user'), n('at', 'Attendance', 'one check-in a day', 3, 0, 'data')], [
      { say: 'HR and admins receive the full list.', on: ['ad'] }, { say: 'A manager receives only the people in their department.', flow: ['ad>mg:narrow'] },
      { say: 'An employee receives only their own record. The server decides, not the front end.', flow: ['mg>em:narrow'] }, { say: 'Attendance allows one check-in and one check-out per employee per day.', flow: ['em>at:today'] }]),
    faqs: [faq('What is soft delete?', 'Marking a record inactive instead of removing it, so history and reports that refer to it keep working.'), faq('Why is hiding rows in the front end not enough?', 'Anyone can call the API without the front end. Only the server can refuse to send data.'), faq('Where should the attendance date come from?', 'From the server clock in a fixed time zone. A client could send any date.')],
  }),

  project({
    no: 6, slug: 'project-6-real-time-chat-application-with-socket-io',
    title: 'A Real-Time Chat Application', meta: 'Project 6: Real-Time Chat with Socket.IO',
    desc: 'Build a chat back end with Socket.IO and Express: JWT-authenticated sockets, private messages, online status, saved history and a REST route to read it.',
    dev: 'supertest socket.io-client', deps: 'express socket.io jsonwebtoken', lib: 'p06-chat.js', test: 'p06.test.js',
    intro: "Chat is the favourite real-time project, because you can see it work with two browser tabs. Under the screen there are three real questions. How do you know who is connecting? How do you deliver a message to exactly one person? And what happens to the messages when the person is offline? This project answers them with Socket.IO for live delivery and a normal REST route for history, which is how real chat apps are built: sockets for what is happening now, HTTP for what has already happened.",
    build: ["Sockets that connect only with a valid JWT.", "Private messages sent to one user, delivered to every device that they have open.", "An online list that updates when people connect or leave.", "Saved history for each pair of users.", "`GET /api/messages/:other` that returns a conversation for the logged-in user."],
    design: ["Each conversation has a key made from the two user ids in sorted order, so that `alice:bob` and `bob:alice` are the same thread. Messages are saved in a `Map` here and in a collection in a real system, with an index on the conversation key and the time. The sender of a message is always taken from the verified token on the socket, never from the message itself, because a message that says `from: someone-else` must not be believed.", "This project builds on lesson 36. Read that first if the words *room* and *handshake* are new."],
    files: [['p06-chat.js', "The chat is created by `createChat`, which returns the HTTP server and the Socket.IO server together. Notice the connection counter: a user is offline only when the last of their sockets closes."], ['p06.test.js', "The test connects two real Socket.IO clients to the server on a free port, and checks delivery, history and presence."]],
    rules: [["Authenticate once, on connect", "The handshake middleware verifies the JWT. A bad token means the connection is refused, so no code that runs afterwards has to wonder who the user is."], ["Validate every message", "A message must be a text, not empty and not too long. Anything else is ignored. Never trust the content just because it came through a trusted connection."], ["Many tabs, one user", "A person may have a phone and a laptop open. Each is a socket in the same private room, so a message reaches both. The online list uses a counter per user, so closing one tab does not make a person look offline."], ["History through HTTP", "When a user opens a conversation, the front end loads the saved messages with a normal request and then listens on the socket for new ones. HTTP is easy to cache, page and secure with the same middleware as the rest of your API."]],
    security: ["Escape message text when you draw it, because a chat is a perfect place for the cross-site scripting of lesson 30. Limit the message size and the number of messages per second for each user, or one client can flood the room.", "With more than one server process, you need the Redis adapter of Socket.IO so that events pass between them, as lesson 36 explains. This project runs in one process."],
    tasks: ["Add a `typing` event that is sent to the other person.", "Add read receipts: a message is marked read when the receiver opens the thread.", "Add group rooms with a membership list that the server checks before joining."],
    checks: ["A socket without a token is refused.", "A message reaches only its receiver.", "A user with two tabs stays online until both close."],
    resume: "\"Built a real-time chat with Socket.IO, JWT-authenticated sockets, private rooms, presence and persistent history\" shows that you can handle more than plain REST.",
    anim: A('Chat in two channels', [n('so', 'Socket', 'JWT checked on connect', 0, 0, 'user'), n('rm', 'Private room', 'user:id', 1, 0, 'tool'), n('hs', 'History', 'saved per pair', 2, 0, 'store'), n('rest', 'GET messages', 'REST for the past', 3, 0, 'out')], [
      { say: 'A socket connects with a token. A bad token is refused.', on: ['so'] }, { say: 'The verified user joins a private room. Messages go to the room of the receiver.', flow: ['so>rm:join'] },
      { say: 'Every message is saved under the conversation key.', flow: ['rm>hs:save'] }, { say: 'Opening a chat loads the past from REST. New messages arrive over the socket.', flow: ['hs>rest:load'] }]),
    faqs: [faq('Why use both sockets and REST?', 'Sockets are best for live events. REST is simple, cacheable and secure for loading the past. Real chat apps use both.'), faq('How do I know who sent a message?', 'From the token that was verified when the socket connected. Never from a field in the message.'), faq('What changes with several servers?', 'Use the Redis adapter, so events pass between server copies, and a load balancer that supports WebSockets.')],
  }),

  project({
    no: 7, slug: 'project-7-hotel-booking-system-with-availability-and-cancellations',
    title: 'A Hotel Booking System', meta: 'Project 7: Hotel Booking System',
    desc: 'Build a hotel booking API in Express: rooms, date-range availability, reservations that cannot overlap, payment and a cancellation rule with a partial refund.',
    deps: 'express jsonwebtoken', lib: 'p07-hotel.js', test: 'p07.test.js',
    intro: "Booking systems look easy and are famous for hiding hard problems. Two guests must never get the same room on the same night. Dates have edge cases. Payments fail halfway. Cancellations have rules. This project is a strong one for a portfolio because its logic is the kind that real companies struggle with, and because it is easy to test: you give it dates, and you check the answer.",
    build: ["Admins add rooms with a number, a type and a price per night in cents.", "`GET /api/availability?checkIn=...&checkOut=...` lists free rooms.", "`POST /api/reservations` reserves a room, charges the payment provider and confirms.", "`POST /api/reservations/:id/cancel` applies the refund rule.", "Clear errors for bad dates, taken rooms and failed payments."],
    design: ["Dates are plain text in the form `2026-12-24`, checked with a pattern and a real calendar check. A stay has a check-in day and a check-out day, and the number of nights is the difference. The most important rule is the overlap rule, and it is easy to get wrong, so it deserves a precise sentence: **two stays overlap when each one starts before the other one ends**. The check-out day is free, so a guest can leave in the morning and the next guest can arrive the same day, and the test checks exactly that.", "Money is in cents, the total is the nights multiplied by the price, and the price comes from the server's room record. The clock is injected, so the test can make a stay start in 30 hours or in 10 days without waiting."],
    files: [['p07-hotel.js', "Read `overlaps` and `isFree` first. The reservation route then applies them in a clear order: validate, check room, check dates, check availability, charge, confirm."], ['p07.test.js', "Three tests: the overlap rule on its own, a full run of availability, booking, double booking and refunds, and a late cancellation together with a failed payment."]],
    rules: [["The overlap rule", "A new stay from `start` to `end` clashes with an existing one from `s` to `e` when `start < e` and `s < end`. If `end` equals `s`, the new guest leaves exactly when the other arrives, and that is allowed. Test the boundary days explicitly."], ["Order of checks", "Cheap checks come first, such as dates and room. The availability check comes right before the payment. In a real database, the check and the creation of the reservation must happen together, with a unique constraint or a transaction, or two requests could both pass the check at the same instant."], ["A failed payment is recorded", "If the provider declines, the reservation is marked `payment_failed` and the reply is 402. The dates are not held. The reservation does not block the room."], ["Cancellation rule", "Cancelling at least 48 hours before check-in gives a full refund, and later gives 50 percent. The rule lives in one small function that is easy to read and test, because a refund rule is exactly the sort of thing that a business will change next month."], ["Own reservations", "A guest can cancel only their own reservation, and an admin can cancel any. Others get 404."]],
    security: ["Do not let the client send the price or the total. Do not accept dates in the past. Reject stays that are unreasonably long, which an attacker could use to block a room for years.", "The refund percentages and the 48-hour rule here are an example and not legal advice. Real businesses must follow the consumer laws of their country and their own published terms."],
    tasks: ["Add a unique index or a transaction so that two simultaneous requests cannot book the same room.", "Add a temporary hold of ten minutes while the guest pays.", "Add seasonal prices, higher at weekends, calculated per night."],
    checks: ["A stay that starts on another stay's check-out day is accepted.", "A declined payment does not block the room.", "Cancelling 10 hours before check-in refunds 50 percent."],
    resume: "\"Implemented a booking engine with date-range availability, overlap detection, payments and a rule-based cancellation policy, covered by boundary-case tests\" is exactly the kind of line that gets questions in an interview.",
    anim: A('A booking request', [n('d', 'Dates', 'checkIn < checkOut', 0, 0, 'check'), n('av', 'Overlap check', 'each starts before other ends', 1, 0, 'tool'), n('pay', 'Payment', 'provider charge', 2, 0, 'cloud'), n('res', 'Confirmed', 'or cancel with refund rule', 3, 0, 'out')], [
      { say: 'The dates are validated: real calendar days, in the future, check-out after check-in.', on: ['d'] }, { say: 'The overlap rule decides if the room is free. A check-out day does not clash.', flow: ['d>av:range'] },
      { say: 'The payment is charged. A decline marks the reservation payment_failed and frees the room.', flow: ['av>pay:amount'] }, { say: 'The reservation is confirmed. Later, a cancellation applies the 48-hour refund rule.', flow: ['pay>res:paid'] }]),
    faqs: [faq('How do I stop double bookings under load?', 'Make the check and the insert one atomic step: a unique constraint, a conditional write or a transaction in the database.'), faq('Why is the check-out day free?', 'The guest leaves in the morning, so the next guest may arrive the same day. The overlap rule uses strict comparisons for this.'), faq('Should the refund rule be in the route?', 'Keep it in its own small function so that it is easy to read, test and change.')],
  }),

  project({
    no: 8, slug: 'project-8-file-upload-and-storage-api-with-quotas-and-cloud-drivers',
    title: 'A File Upload and Storage API', meta: 'Project 8: File Upload and Storage API',
    desc: 'Build a personal file storage API in Express: uploads checked by real file type, per-user quotas, private downloads and a driver for local disk or ImageKit.',
    deps: 'express multer jsonwebtoken', lib: 'p08-files.js', test: 'p08.test.js',
    intro: "Almost every product stores files: profile pictures, invoices, resumes, attachments. This project is a small version of a cloud drive: users upload files, list them, download them and delete them, and every file belongs to its owner. It combines three earlier lessons, the safe uploads of lesson 22, the roles and tokens of lesson 27 and the interface idea of dependency injection, so that the bytes can live on a disk today and in the cloud tomorrow.",
    build: ["`POST /api/files` uploads a file in the field `file`, for logged-in users.", "Allowed types: PNG, JPEG, PDF and plain text, from an allow-list.", "A storage quota for each user.", "`GET /api/files` lists your files, and `GET /api/files/:id` downloads one.", "`DELETE /api/files/:id` removes the bytes and the record.", "A driver with three functions, `put`, `get` and `remove`, so that storage is replaceable."],
    design: ["Two things are stored for each upload: the **bytes**, which go to the driver under a random key, and a **record**, with the owner, the original name, the real type, the size and the key. The user's original file name is kept only as a label. It is never used to build a path. The record is what the API lists and checks. A file belongs to a person if and only if `record.ownerId` equals the user from the token.", "Because the driver is a small interface, the tests run with a folder in the operating system's temporary directory, and production can use a cloud driver. The second file below shows the same three functions on ImageKit, which is how the main server of this site stores its images. It was **not run**, because it needs an account and keys, so read it as a pattern and follow the current documentation of the service."],
    files: [['p08-files.js', "The API and the local-folder driver. Read the upload route to see the order of checks: type, then quota, then save."], ['p08-cloud-driver.js', "The same driver interface for ImageKit. For cloud storage, you normally serve files by URL, so `get` explains that."], ['p08.test.js', "The test uploads allowed files, an `.exe` file, a file that is too large and uploads that pass the quota, and then tests downloads and deletes by the owner and by someone else."]],
    rules: [["An allow-list of types", "Only four types are accepted, and anything else is refused with **415**. This project trusts the type that the upload declares. That is a weakness, because a client can lie about it, and lesson 22 shows the stronger check of reading the first bytes. Adding that check is the first extension task."], ["A quota per user", "Before saving, the code adds the new size to what the user already stores. If the total goes above the quota, the reply is **413**. Without a quota, one account can fill your disk or your cloud bill."], ["404 instead of 403", "If the file exists but belongs to someone else, the reply is `File not found`. A 403 would reveal that a file with that id exists, and ids can be guessed."], ["Clean up both sides", "Deleting removes the bytes from the driver and the record from the list. If the first step fails, the record must stay, so you can try again."], ["Download headers", "Send the stored type, and for types that a browser could run, such as HTML, force a download with `Content-Disposition: attachment`. This project does not allow HTML at all."]],
    security: ["The names given by the user are never part of a path, and the key is a random UUID with an extension that the server chose. Files are stored outside the folders that Express serves as static content. Ask whether uploaded files could contain malware, and if the files are shared with others, add a virus scan.", "Edge cases are where upload bugs live, so test a file that is too large, a type that is not allowed, and a user who is exactly at the limit of the quota."],
    tasks: ["Add the first-bytes type check from lesson 22 and a test with a fake PNG.", "Write a driver for Amazon S3 or Cloudinary from the three-function interface.", "Add signed, expiring download links.", "Add folders, with a rule that a user cannot see another user's folders."],
    checks: ["An `.exe` upload is refused with 415.", "Another user receives 404 for your file.", "Deleting removes both the record and the stored bytes."],
    resume: "\"Built a file storage API with an allow-list of types, per-user quotas, owner-only access and a swappable storage driver for local disk and ImageKit\" describes it well. Do not claim the cloud driver works in production unless you have run it.",
    anim: A('Upload to storage', [n('up', 'Upload', 'multipart, 1 file', 0, 0, 'user'), n('ty', 'Checks', 'real type, size, quota', 1, 0, 'check'), n('dr', 'Driver', 'put under random key', 2, 0, 'tool'), n('rc', 'Record', 'owner, name, size', 3, 0, 'store')], [
      { say: 'A logged-in user uploads one file.', on: ['up'] }, { say: 'The server checks the real type from the first bytes and the user quota.', flow: ['up>ty:buffer'] },
      { say: 'The driver saves the bytes under a random key. It could be disk or cloud.', flow: ['ty>dr:put'] }, { say: 'A record links the key to the owner. Only the owner can list, download or delete.', flow: ['dr>rc:save'] }]),
    faqs: [faq('Why does the driver have only three functions?', 'A small interface is easy to implement for any storage and easy to replace without changing the API.'), faq('Why hide that a file exists?', 'Ids can be guessed. Answering 404 for someone else\'s file tells a stranger nothing.'), faq('Disk or cloud storage?', 'Disk is fine for one server and small apps. Cloud storage suits several servers, large files and public delivery.')],
  }),

  project({
    no: 9, slug: 'project-9-saas-subscription-backend-with-plans-limits-and-billing-webhooks',
    title: 'A SaaS Subscription Back End', meta: 'Project 9: SaaS Subscription Back End',
    desc: 'Build a subscription back end in Express: plans, checkout, entitlement limits per plan, and billing events from a signed, idempotent webhook with past-due.',
    deps: 'express jsonwebtoken', lib: 'p09-saas.js', test: 'p09.test.js',
    intro: "A SaaS product earns money from subscriptions, and behind every pricing page there is a back end that answers one question on every request: *what is this account allowed to do right now?* This project builds that core. It has plans with limits, a way to start a subscription, a webhook that activates the plan only when the provider confirms payment, and a limit check on the feature that is being sold. It combines the payment rules of lesson 37 with the access control of Project 3.",
    build: ["`GET /api/plans` shows the plans and their limits.", "`POST /api/subscribe` starts a checkout for a paid plan. It does **not** activate it.", "`POST /webhooks/billing` receives signed events that activate, renew or mark an account past due.", "`GET /api/account` shows the plan, its limits and the current usage.", "`POST /api/projects` creates a project only if the plan allows more of them."],
    design: ["There are three plans, `free`, `pro` and `team`, each with a price in cents and a limit for the number of projects. The prices in the code are only an example, and your own product will have its own. The account of each user has a plan, a status and a renewal date. The rule that makes billing safe is: **the plan changes only because of a verified webhook, never because the client says so, and never because the browser came back from the payment page**.", "The limit check is called an **entitlement check**. It runs on the server on every request that uses a limited feature, and it reads the current plan from your own data. A front end can show a locked button to be polite, but the real lock is the check in the route."],
    files: [['p09-saas.js', "Read the webhook first: signature, duplicate check, then the state change. Then read the entitlement check in the projects route."], ['p09.test.js', "The test subscribes, shows that the plan is still free, sends a signed webhook, and then shows that the limit has risen. It also tests a duplicate event and a payment failure."]],
    rules: [["Subscribe starts, the webhook finishes", "`/api/subscribe` asks the billing provider for a checkout link and returns it. The account stays on its old plan. Only a verified `subscription.paid` event changes the plan, and the test proves that the plan does not change before the webhook."], ["Signed and raw", "The webhook route is registered before `express.json()` and uses the raw body for the HMAC check, as in lesson 37, with a constant-time comparison."], ["Idempotent events", "The id of every event is remembered, and a repeated event is acknowledged without being applied twice. A renewal that was counted twice would extend an account for free."], ["Past due", "When a payment fails, the status becomes `past_due`, and the projects route answers **402** with a clear message. You decide the policy: many products give a grace period before they limit a feature."], ["Limits on every request", "The number of projects is compared with the limit of the current plan at the moment of creation. A free account that tries to create a second project gets **403**, and the same request works after the paid webhook. A downgrade or a failed payment takes effect immediately."]],
    security: ["Never trust a plan name from the client in the webhook either. The provider event should contain an id that you created during checkout, which you map back to your own record. Prices, taxes and invoices follow the laws of your country, and a real provider handles much of that for you. This project is a learning model, not an accounting system.", "A real provider has its own library, event names and signature header, so follow its current documentation. This lesson uses a fake provider, so that the logic can be run and tested."],
    tasks: ["Add a `team` seat limit and an invite route that respects it.", "Add a yearly plan with a renewal date, and a job from lesson 35 that reminds people before renewal.", "Add a customer portal route for cancellation that takes effect at the end of the period."],
    checks: ["Subscribing does not change the plan by itself.", "A repeated webhook is applied once.", "A past-due account is refused with 402 on limited features."],
    resume: "\"Built a subscription back end with plan limits, signed idempotent billing webhooks and past-due handling\" is concise and shows that you understand what a paid product needs.",
    anim: A('A plan changes only by webhook', [n('sub', 'Subscribe', 'starts checkout only', 0, 0, 'user'), n('prov', 'Provider', 'takes payment', 1, 0, 'cloud'), n('wh', 'Webhook', 'signed, once', 2, 0, 'check'), n('lim', 'Entitlement', 'limits per request', 3, 0, 'tool')], [
      { say: 'The client asks to subscribe. The server returns a checkout link and changes nothing.', on: ['sub'] }, { say: 'The provider takes the payment on its own page.', flow: ['sub>prov:checkout'] },
      { say: 'The signed webhook arrives. A verified, first-time event activates the plan.', flow: ['prov>wh:paid'] }, { say: 'Each limited feature checks the plan, and a past-due account is refused.', flow: ['wh>lim:plan'] }]),
    faqs: [faq('What is an entitlement check?', 'A server-side check, on every request, that the account\'s current plan allows the feature or the amount that the request needs.'), faq('Why not activate the plan when the user returns from checkout?', 'Anyone can open the return URL. Only a signed message from the provider proves that money moved.'), faq('What is past due?', 'The state of an account whose latest payment failed. Products usually limit features, with or without a grace period, until it is fixed.')],
  }),

  project({
    no: 10, slug: 'project-10-microservices-app-with-gateway-events-and-health-checks',
    title: 'A Microservices Application', meta: 'Project 10: Microservices with Gateway',
    desc: 'Build a small microservices system in Node.js: users, orders and notifications services, an API gateway that checks tokens, an event broker and health checks.',
    deps: 'express jsonwebtoken', lib: 'p10-microservices.js', test: 'p10.test.js',
    intro: "The last project is the one that people find hardest to picture, so it is built to be small and runnable. Instead of one app, there are three small services and a front door. Each service has one job, they talk to each other over HTTP and through an event broker, and the only way in from the outside is the gateway. It runs in one process for the test, but every part uses its own port and could be moved to its own machine, which is the whole point. Read lesson 38 first for the reasons to split, and the reasons not to.",
    build: ["A **users service** that owns user data.", "An **orders service** that creates orders, asks the users service who the customer is, and publishes an `order.created` event.", "A **notifications service** that listens for events and reacts, with no HTTP call from the orders service.", "An **API gateway**, the only public address. It checks the JWT and forwards requests to the right service.", "`/health` on every service, a 504 for timeouts at the gateway and a clear 503 when a dependency is down."],
    design: ["Each service owns its own data, and nobody reads another service's data directly. The orders service does not open the users data. It asks the users service over HTTP. That is the rule that makes the services independent, and it costs something: a network call can fail, so there must be a timeout and an error. For work that does not need an answer, such as sending a notification, the orders service **publishes an event** to a broker, and the notifications service subscribes. The orders service neither knows nor cares who listens. In this project the broker is a few lines on top of `EventEmitter`. In production it would be Redis with BullMQ, RabbitMQ or Kafka, as in lesson 35.", "The gateway checks the token once and then forwards the request, so the services behind it can trust that the caller was checked. This only works if the services are not reachable from the internet, so in a real system they sit on a private network, as the Compose file below shows."],
    files: [['p10-microservices.js', "All four parts in one file so that you can read the whole system. Each `start...` function creates one service on a free port and returns its URL."], ['p10-docker-compose.yml', "How the same four parts would run as containers. This file was **not run**. Only the gateway publishes a port to the outside."], ['p10.test.js', "The test starts all the services, logs in through the gateway, creates an order and waits for the notification, and then stops the users service to see that the orders service answers with a clear 503."]],
    rules: [["Synchronous and asynchronous calls", "Use a direct HTTP call when you need the answer now, such as *who is this customer*. Use an event when you only need to say *this happened*. Events keep services loosely coupled, and they let you add new reactions without changing the sender."], ["Timeouts everywhere", "Every call between services has a timeout, using `AbortSignal.timeout` as in lesson 23. When a service does not answer in time, the gateway returns **504** instead of hanging. When the orders service cannot reach the users service at all, it answers **503** with a plain message."], ["A single public door", "Only the gateway is exposed. It verifies the JWT, and the services trust what comes through it. Do not let outside traffic reach a service directly."], ["Health checks", "Each service has `/health`. A load balancer, Docker or an uptime tool calls it and replaces or avoids a sick service."], ["Failure is normal", "The test stops one service on purpose and checks that the system fails in a controlled way. When you design for several services, think about what happens when each of them is down."]],
    security: ["Services should not trust each other blindly. A production system adds service-to-service authentication, and keeps private networks, logs with a shared request id, and monitoring. Distributed systems also make data consistency harder: an order may exist while its notification is still on the way. Think about retries and idempotency as in lessons 35 and 37.", "Be honest about the trade. For most projects, one well-organised app is easier to build, test and run. Choose several services when you can say why, and be ready to explain that choice in an interview."],
    tasks: ["Add a fourth service for products and make the orders service check stock through it.", "Pass a request id from the gateway to every service and log it, as in lesson 33.", "Replace the broker with BullMQ and Redis, and run everything with Docker Compose."],
    checks: ["The only public address is the gateway.", "A stopped users service gives a clear 503 and not a hang.", "The notification arrives without the orders service calling it."],
    resume: "\"Built a small microservices system with an API gateway, service-to-service calls with timeouts, an event broker and health checks\" is a precise line. Say clearly that it was a learning project, and what you would add for production.",
    anim: A('One door, three services', [n('gw', 'Gateway', 'checks the JWT', 0, 0, 'check'), n('us', 'Users', 'owns user data', 1, 0, 'store'), n('or', 'Orders', 'asks users, publishes', 2, 0, 'app'), n('no', 'Notifications', 'listens to events', 3, 0, 'out')], [
      { say: 'The gateway is the only public address. It verifies the token and forwards the request.', on: ['gw'] }, { say: 'The orders service asks the users service who the customer is, with a timeout.', flow: ['gw>us:who is it'] },
      { say: 'Orders saves the order and publishes order.created. It does not call anyone else.', flow: ['us>or:customer'] }, { say: 'The notifications service reacts to the event on its own.', flow: ['or>no:event'] }]),
    faqs: [faq('Why not let services read each other\'s databases?', 'Shared databases couple the services together, so changing one breaks the others. Each service should own its data and share it through its API or events.'), faq('Why publish an event instead of calling the notification service?', 'The orders service does not need an answer, and an event lets you add or remove listeners without changing the sender.'), faq('Is this how real companies do it?', 'The ideas are the same. Real systems add message brokers like RabbitMQ or Kafka, service meshes, tracing and orchestration such as Kubernetes.')],
  }),
];
